import 'package:go_router/go_router.dart';

import 'routes.dart';

/// Central GoRouter instance.
///
/// Feature jobs (J4–J13) do NOT edit this file. Instead they append their
/// `RouteBase` entries to [appRoutes] (exported from `routes.dart`), which is
/// referenced here. This keeps GoRouter centralization without cross-scope edits.
///
/// The app boots at [Routes.splash]; [SplashPage] plays the launch animation and
/// then replaces the stack with [Routes.home] (the dashboard). The dashboard's
/// `/` route is owned solely by `routes.dart` — do NOT re-register `/` here, or
/// GoRouter's first-match wins and the dashboard becomes unreachable.
final GoRouter appRouter = GoRouter(
  initialLocation: Routes.splash,
  routes: <RouteBase>[...appRoutes],
);
